#version 300 es

#define HLSLCC_ENABLE_UNIFORM_BUFFERS 1
#if HLSLCC_ENABLE_UNIFORM_BUFFERS
#define UNITY_UNIFORM
#else
#define UNITY_UNIFORM uniform
#endif
#define UNITY_SUPPORTS_UNIFORM_LOCATION 1
#if UNITY_SUPPORTS_UNIFORM_LOCATION
#define UNITY_LOCATION(x) layout(location = x)
#define UNITY_BINDING(x) layout(binding = x, std140)
#else
#define UNITY_LOCATION(x)
#define UNITY_BINDING(x) layout(std140)
#endif
layout(std140) uniform v_buffer0 {
	vec4 v_cb0[8];
} _v_buffer0;
layout(std140) uniform v_buffer1 {
	vec4 v_cb1;
} _v_buffer1;
layout(std140) uniform v_buffer2 {
	vec4 v_cb2[4];
} _v_buffer2;
layout(std140) uniform v_buffer3 {
	vec4 v_cb3[5];
} _v_buffer3;
in highp vec4 in_POSITION0;
in highp vec2 in_TEXCOORD0;
in highp vec2 in_TEXCOORD1;
in highp vec4 in_COLOR0;
out highp vec2 vs_TEXCOORD0;
out highp vec2 vs_TEXCOORD1;
out highp vec2 vs_TEXCOORD2;
out highp vec4 vs_COLOR0;
vec4 u_xlat0;
float u_xlat1;
float u_xlat2;
vec3 u_xlat3;
vec2 u_xlat8;
void main()
{
    u_xlat0 = in_POSITION0.yyyy * _v_buffer2.v_cb2[1];
    u_xlat0 = _v_buffer2.v_cb2[0] * in_POSITION0.xxxx + u_xlat0;
    u_xlat0 = _v_buffer2.v_cb2[2] * in_POSITION0.zzzz + u_xlat0;
    gl_Position = _v_buffer2.v_cb2[3] * in_POSITION0.wwww + u_xlat0;
    u_xlat0.xy = _v_buffer0.v_cb0[3].yz + vec2(0.5, 0.5);
    u_xlat8.xy = in_TEXCOORD0.xy * _v_buffer0.v_cb0[7].xy + _v_buffer0.v_cb0[7].zw;
    u_xlat0.xy = (-u_xlat0.xy) + u_xlat8.xy;
    vs_TEXCOORD0.xy = u_xlat8.xy;
    u_xlat0.xy = u_xlat0.xy * _v_buffer0.v_cb0[3].ww;
    u_xlat8.x = _v_buffer0.v_cb0[3].x * _v_buffer1.v_cb1.x;
    u_xlat1 = sin(u_xlat8.x);
    u_xlat2 = cos(u_xlat8.x);
    u_xlat3.z = u_xlat1;
    u_xlat3.y = u_xlat2;
    u_xlat3.x = (-u_xlat1);
    u_xlat8.y = dot(u_xlat0.xy, u_xlat3.xy);
    u_xlat8.x = dot(u_xlat0.xy, u_xlat3.yz);
    vs_TEXCOORD1.xy = u_xlat8.xy + vec2(0.5, 0.5);
    vs_TEXCOORD2.xy = in_TEXCOORD1.xy * _v_buffer0.v_cb0[7].xy + _v_buffer0.v_cb0[7].zw;
    u_xlat0 = _v_buffer3.v_cb3[4] * vec4(2.0, 2.0, 2.0, 2.0) + _v_buffer0.v_cb0[1];
    u_xlat0 = u_xlat0 + (-in_COLOR0);
    vs_COLOR0 = _v_buffer0.v_cb0[6].yyyy * u_xlat0 + in_COLOR0;
    return;
}

